WITH base AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, UPPER(full_name) AS full_name_upper, COALESCE(job_title, 'DIRECT') AS resolved_job_title FROM employees WHERE hire_date > DATE '2023-04-04' AND full_name NOT LIKE '%Won%'), scored AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, full_name_upper, resolved_job_title, NTILE(5) OVER w_recent AS salary_bucket, LAST_VALUE(job_title) IGNORE NULLS OVER w_grp AS last_known_job_title, FIRST_VALUE(job_title) IGNORE NULLS OVER w_grp_2 AS first_known_job_title FROM base WINDOW w_recent AS (PARTITION BY level ORDER BY salary, id), w_grp AS (PARTITION BY manager_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp_2 AS (PARTITION BY dept_id, job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched AS (SELECT src.*, p.full_name AS employee_full_name, p.salary AS employee_salary, p.job_title AS employee_job_title FROM scored src INNER JOIN employees p ON src.manager_id = p.id), with_dims AS (SELECT src.*, e.job_title AS employee_job_title_2, e.salary AS employee_salary_2 FROM enriched src LEFT JOIN employees e ON src.manager_id = e.id), filtered AS (SELECT *, LENGTH(full_name) AS full_name_length, LOWER(email) AS email_lower, COALESCE(job_title, 'DIRECT') AS resolved_job_title_2 FROM with_dims WHERE hire_date >= TO_DATE('2023-05-29') AND job_title IS NOT NULL) SELECT id, full_name, email, dept_id, salary, hire_date, is_remote, level, resolved_job_title, CASE WHEN level RLIKE '^(L2|L1)$' THEN 'OTHER_ZONE' WHEN level RLIKE '^(L3|L4)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS level_zone FROM filtered;
